import { colors, Theme, useTheme } from '@/theme'
import { AnimatedTouchableOpacity, AnimatedText } from '../animated'
import { defineStyles } from '@/utils/defineStyles'
import { LinearGradient } from 'expo-linear-gradient'
import { ActivityIndicator } from 'react-native'

interface ButtonProps {
	text: string
	disabled?: boolean
	onPress?: () => void
	variant?: 'default' | 'destructive' | 'gradient'
	loading?: boolean
}

export const Button = ({
	text,
	disabled,
	onPress,
	variant = 'default',
	loading = false
}: ButtonProps) => {
	const { theme } = useTheme()
	const isDisabled = disabled || loading

	return (
		<AnimatedTouchableOpacity
			style={styles.button(theme, isDisabled, variant)}
			onPress={onPress}
			disabled={isDisabled}
		>
			{loading && (
				<ActivityIndicator size="small" color={colors[theme].gray[25]} />
			)}
			{!loading && (
				<>
					{variant === 'gradient' && !isDisabled && (
						<LinearGradient
							colors={[colors[theme].gray[900], colors[theme].gray[700]]}
							style={styles.gradientBackground}
						/>
					)}
					<AnimatedText style={styles.buttonText(theme, isDisabled, variant)}>
						{text}
					</AnimatedText>
				</>
			)}
		</AnimatedTouchableOpacity>
	)
}

const styles = defineStyles({
	button: (
		theme: Theme,
		disabled?: boolean,
		variant: 'default' | 'destructive' | 'gradient' = 'default'
	) => ({
		overflow: 'hidden',
		backgroundColor: disabled
			? colors[theme].gray[50]
			: variant === 'destructive'
			? colors[theme].red[300]
			: variant === 'gradient'
			? 'transparent'
			: colors[theme].gray[900],
		borderRadius: 20,
		borderCurve: 'continuous',
		paddingVertical: 18,
		alignItems: 'center',
		transitionProperty: ['backgroundColor', 'color'],
		transitionDuration: '300ms'
	}),
	gradientBackground: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		borderRadius: 20,
		borderCurve: 'continuous'
	},
	buttonText: (
		theme: Theme,
		disabled?: boolean,
		variant: 'default' | 'destructive' | 'gradient' = 'default'
	) => ({
		fontSize: 16,
		fontWeight: '600',
		color: disabled
			? colors[theme].gray[400]
			: variant === 'destructive'
			? colors.dark.gray[900]
			: colors[theme].gray[25],
		transitionProperty: ['color'],
		transitionDuration: '300ms'
	})
})
